INTRO = "In the final scene of Episode 2, Baek Seung-chan obeys Ra Joon-mo's ban on speaking by silently setting Youn Yuh-jung's plum tea on the editing desk. Then a warm flashback shows how Ye-jin came to live at Joon-mo's flat: worried she might stay in a cramped motel, Joon-mo stamps his own thumbprint onto her roommate pledge. Listen to the Korean first, then we'll go through it together."
OPENER = "Now let's go through it line by line with the English translation."
TRANSITION = "Now let's listen to the whole conversation one last time."
OUTRO = 'You heard Seung-chan silently deliver the plum tea at the editing desk, followed by the warm flashback of Joon-mo welcoming Ye-jin into his home. See you next time.'
CLOSING = ('yejin', '다음에 만나요!')

STORY = [('joonmo', '야, 이거 뭐야? 안 들려?', "Hey, what is this? Can't you hear me?", [(1129, '야 이거 뭐야 안 들려?')], ''), ('joonmo', '이게 뭔지 말해야 될 거 아니야!', 'You have to tell me what this is!', [(1131, '이게 뭔지 말해야 될 거 아니야')], ''), ('seungchan', '윤여정 선생님이 선배님께 전해드리라고 하셨습니다.', 'Ms. Youn Yuh-jung asked me to pass this to you.', [(1132, '윤여정 선생님이 선배님께 전해드리라고')], 'Completes polite verb 하셨습니다.'), ('seungchan', '그동안 재밌었다는 말도 같이 전해달라고 하셨습니다.', 'She also asked me to tell you she had fun all this time.', [(1133, '그동안 재밌었다는 말도 같이')], 'Completes polite clause.'), ('joonmo', '너 그걸 이제 말하면 어떡해?', 'How can you tell me that only now?', [(1134, '너 그걸 이제 말하면')], 'Uses standard 어떡해 for caption 어떻게.'), ('seungchan', '말 걸지 말라고 하셔서요.', 'Because you told me not to speak to you.', [(1135, '말 걸지 말라고 하셔서')], 'Adds polite -요 ending.'), ('joonmo', '아, 이건 말을 했었어야지!', 'Ah, you still should have told me about this!', [(1136, '아 이건 말을 했었어야지')], ''), ('yejin', '모텔 같은 데 장기투숙이나 해야지 뭐.', "I suppose I'll just stay long-term at a motel or somewhere.", [(1153, '모텔 같은데'), (1153, '장기투숙이나 해야지 뭐')], 'Uses standard spacing 같은 데.'), ('yejin', '너 나중에 딴소리 하기 없기다.', 'No going back on your word later.', [(1155, '너 나중에 딴소리 하기 없기다')], ''), ('joonmo', '진짜 딴소리 안 해.', "I really won't go back on my word.", [(1156, '진짜 딴소리 안 해')], ''), ('joonmo', '내가 도장 한 번 더 찍어줄게.', 'I will stamp my seal one more time for good measure.', [(1164, '내가 도장 한 번'), (1164, '더 찍어줄게')], ''), ('yejin', '감사합니다.', 'Thank you very much.', [(1165, '감사합니다.')], '')]

WALK = [(0, None, "'Hey, what is this? Can't you hear me?'"), (1, None, "'You have to tell me what this is!'"), (2, None, "'Ms. Youn Yuh-jung asked me to pass this to you.'"), (3, None, "'She also asked me to tell you she had fun all this time.'"), (4, None, "'How can you tell me that only now?'"), (5, None, "'Because you told me not to speak to you.'"), (6, None, "'Ah, you still should have told me about this!'"), (7, None, "'I suppose I'll just stay long-term at a motel or somewhere.'"), (8, None, "'No going back on your word later.'"), (9, None, "'I really won't go back on my word.'"), (10, None, "'I will stamp my seal one more time for good measure.'"), (11, None, "'Thank you very much.'")]
